import{_ as t,o as a,c as n,ag as r}from"./chunks/framework.ePeAWSvT.js";const u=JSON.parse('{"title":"October 2026","description":"","frontmatter":{},"headers":[],"relativePath":"guide/release-october-2026.md","filePath":"guide/release-october-2026.md"}'),o={name:"guide/release-october-2026.md"};function i(s,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="october-2026" tabindex="-1">October 2026 <a class="header-anchor" href="#october-2026" aria-label="Permalink to &quot;October 2026&quot;">​</a></h1><p>Changes since the July 2026 release, across the platform, connectors, agents and the admin experience.</p><nav class="table-of-contents"><ul><li><a href="#new-connectors-integrations">New Connectors &amp; Integrations</a><ul><li><a href="#invoicing-over-the-sap-ariba-network">Invoicing over the SAP Ariba Network</a></li></ul></li><li><a href="#mapping-data-sync">Mapping &amp; Data Sync</a></li><li><a href="#performance">Performance</a></li><li><a href="#warehouse-inventory-data-model">Warehouse &amp; Inventory Data Model</a></li><li><a href="#configuration-builder-experience">Configuration Builder Experience</a></li><li><a href="#ai-assistant-data-access">AI &amp; Assistant Data Access</a></li><li><a href="#search-indexing">Search &amp; Indexing</a></li><li><a href="#agents-on-premise">Agents &amp; On-Premise</a></li><li><a href="#reliability-monitoring">Reliability &amp; Monitoring</a></li><li><a href="#documentation">Documentation</a></li><li><a href="#upgrade-notes">Upgrade Notes</a></li></ul></nav><h2 id="new-connectors-integrations" tabindex="-1">New Connectors &amp; Integrations <a class="header-anchor" href="#new-connectors-integrations" aria-label="Permalink to &quot;New Connectors &amp; Integrations&quot;">​</a></h2><p><strong>New connectors:</strong> Epicor Kinetic (manufacturing ERP), Epicor Prophet 21 (distribution ERP), Jira (issue tracking), Ordoro (order &amp; inventory management), and Finexio (payments). Sage Intacct now runs on that vendor&#39;s REST API.</p><ul><li><strong>Failures that used to look like successes are now caught</strong> — Some systems accept a write with an HTTP 200 and report the rejection inside the response body. Central used to record those as successful syncs. It now inspects the response and fails the sync, so a record the other system actually refused no longer shows as delivered.</li><li><strong>You can see why a system said no</strong> — When a connected system rejects a request, you get its own explanation rather than a generic wrapper. More than half the connector catalogue previously surfaced no error text at all; those now report a usable message, and Sage Intacct and Rent Manager failures in particular are no longer blank.</li><li><strong>More systems can notify you of changes</strong> — Webhook support was added for Payload and Loopio and enabled for Paycor, so those systems can push changes to you instead of waiting for the next scheduled poll.</li><li><strong>Large reads are more dependable</strong> — BILL now pages through long result sets correctly, Wherefour retries instead of failing when it asks you to come back later, and QuickBooks Time accepts the dates Central sends.</li><li><strong>Fixes</strong> — Cincom CPQ connects again, Active Directory / LDAP endpoints can be created, and picking a system that comes in several flavours (SAP Ariba, Rental Result) no longer errors.</li></ul><h3 id="invoicing-over-the-sap-ariba-network" tabindex="-1">Invoicing over the SAP Ariba Network <a class="header-anchor" href="#invoicing-over-the-sap-ariba-network" aria-label="Permalink to &quot;Invoicing over the SAP Ariba Network&quot;">​</a></h3><p>Central can now send cXML invoices to the Ariba Network, including the PDF the buyer expects attached to them.</p><ul><li><strong>Attach the invoice document</strong> — Author attachments directly in the endpoint configuration, and Central sends the invoice and its PDF together as a single request.</li><li><strong>Match invoices to their purchase order</strong> — Invoices link back to the originating PO, including when the buyer&#39;s document arrives without a payload identifier.</li><li><strong>Control the document header</strong> — Set the XML declaration and DOCTYPE per endpoint where a trading partner requires its own.</li></ul><h2 id="mapping-data-sync" tabindex="-1">Mapping &amp; Data Sync <a class="header-anchor" href="#mapping-data-sync" aria-label="Permalink to &quot;Mapping &amp; Data Sync&quot;">​</a></h2><ul><li><strong>Match incoming records on more than their keys</strong> — When an inbound message carries no key Central recognises, it can now look the record up by properties you nominate — an email address, an account code, a reference number. The key is attached to the record already there instead of a duplicate being created. More than one match is reported as an error rather than silently taking the first.</li><li><strong>Put a stored setting or secret into a request</strong> — A new <em>Connector Setting</em> map source places a connector setting straight into a request body, on reads as well as writes, with secrets kept out of logs. Useful for systems that expect a shared secret in every call rather than in a header.</li><li><strong>Decline records you can&#39;t place</strong> — A new <em>Unresolved Record Handling</em> option lets an endpoint refuse to create a record whose reference it can&#39;t resolve, so a half-formed orphan isn&#39;t created while the real record is still on its way.</li><li><strong>Page the way each endpoint needs to</strong> — Choose a paging approach and page size per endpoint instead of inheriting the connector&#39;s, from a dedicated Paging tab.</li><li><strong>Collapse a collection into one value</strong> — Render a list of values coming from a connector into a single field.</li><li><strong>Apply a filter only to certain operations</strong> — Scope a subscriber filter so it applies to new records but not updates, or the reverse.</li><li><strong>Resolve references by Central&#39;s own ID</strong> — Useful where the two systems share no common identifier.</li><li><strong>Borrow a value from the parent record</strong> — <em>Map From Parent</em> now works on looping-list maps, with the right parent fields offered in the picker.</li><li><strong>Date transforms are selectable again</strong> — The date-adjustment and date-only transforms were missing from the endpoint transform picker, and date-adjustment rejected text dates. Both work.</li><li><strong>Fewer silent surprises</strong> — An empty source value no longer produces a blank downstream record; a property that can&#39;t be resolved fails loudly instead of being quietly set aside; an empty XML attribute writes as empty instead of failing the whole document; and a map naming its own system is no longer dropped from key replication.</li><li><strong>Keys arrive more reliably</strong> — Keys captured on child records now replicate, a key is only reported when its value actually changed, and a record carrying duplicate keys for one system returns a clear error instead of a retried server failure.</li></ul><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><ul><li><strong>Large reads are dramatically faster</strong> — A rebuilt connector read path cut a representative large read from <strong>22 seconds to under one</strong>, and its memory use by about 94%. Big paged pulls and wide line-item sets finish faster and are far less likely to time out.</li><li><strong>Faster cross-entity questions</strong> — Queries that filter one entity by a related one now run as a single operation instead of one query per row; a report that took around twenty seconds returns in about one.</li></ul><h2 id="warehouse-inventory-data-model" tabindex="-1">Warehouse &amp; Inventory Data Model <a class="header-anchor" href="#warehouse-inventory-data-model" aria-label="Permalink to &quot;Warehouse &amp; Inventory Data Model&quot;">​</a></h2><ul><li><strong>New warehouse task types</strong> — Receiving Task and Putaway Task join Pick, Pack and Wave as types of <strong>Warehouse Task</strong>, and two new entity types arrive alongside them: <strong>Warehouse Task Line</strong> and <strong>Inventory Balance</strong>. Inventory Change Event and its lines are also now modelled.</li><li><strong>Richer sales order lines</strong> — Sales order line items carry cost, margin and fulfillment quantity.</li><li><strong>Renamed for consistency</strong> — The Pick, Pack and Wave task types introduced in v5.15 are now <strong>Pick Task</strong>, <strong>Pack Task</strong> and <strong>Wave Task</strong>, and the Wave Item entity type is now <strong>Warehouse Task Line</strong>. See <a href="#upgrade-notes">Upgrade Notes</a>.</li></ul><h2 id="configuration-builder-experience" tabindex="-1">Configuration Builder Experience <a class="header-anchor" href="#configuration-builder-experience" aria-label="Permalink to &quot;Configuration Builder Experience&quot;">​</a></h2><ul><li><strong>Start from a worked example</strong> — Shipped endpoint templates for Paycor, Office 365, Deltek Vantagepoint and QuickBooks Time give you a configured starting point instead of a blank endpoint. Templates can also carry universal filters.</li><li><strong>Run a subscriber over just what you need</strong> — Trigger a run with filters applied and variables overridden, instead of re-running everything to re-send a handful of records.</li><li><strong>Reorder mappings by dragging</strong> — Drag to reorder maps within a list, and to move them into child groups.</li><li><strong>Send one record to several destinations</strong> — Where a record carries a list of destinations, configure Central to deliver it to each of them.</li><li><strong>Author projections from the parent</strong> — Build a projection starting from its parent record, with its type field filled in for you.</li><li><strong>Export your data model</strong> — Produce a document of the common model you&#39;re working against, including Excel, for anyone documenting the integration.</li><li><strong>Settings organised by direction</strong> — The Endpoint Settings tab is grouped into inbound and outbound, so you only see what applies.</li><li><strong>Templates that finish the job</strong> — A data provider added from a template now creates and binds its data model instead of arriving unbound.</li><li><strong>Caught earlier</strong> — Duplicate endpoint IDs and names are flagged within and across hubs, and a read-shaped endpoint that isn&#39;t typed as a data provider is called out.</li><li><strong>Fixes</strong> — Delete spinners stop when a delete fails, monitor date-range grids reload with the range you actually picked rather than the previous one, and Maintain Index shows schemas on deprecated entity types again.</li></ul><h2 id="ai-assistant-data-access" tabindex="-1">AI &amp; Assistant Data Access <a class="header-anchor" href="#ai-assistant-data-access" aria-label="Permalink to &quot;AI &amp; Assistant Data Access&quot;">​</a></h2><ul><li><strong>Ask for a total without reading every row</strong> — Totals, averages and counts can now be computed over a saved query&#39;s results in a single answer. A question like &quot;total hours in August per person&quot; over hundreds of entries is answered directly, where before the underlying rows wouldn&#39;t fit in one response.</li><li><strong>Scope a saved query to whoever is asking</strong> — A saved query can filter to the signed-in user, so the same question returns each person&#39;s own data.</li><li><strong>Filters return what you&#39;d expect</strong> — Comparisons against numbers, dates and true/false values work rather than erroring, and date ranges return real results instead of silently returning nothing.</li><li><strong>Date comparisons across related records are correct</strong> — Same-day records are no longer counted as late.</li><li><strong>The assistant describes your data accurately</strong> — Field lists are complete, a repeated property name no longer takes out a whole data model, and related records are named so two different relationships can&#39;t be confused for one.</li><li><strong>Use Central from ChatGPT</strong> — Central can be added as a connector in ChatGPT, with sign-in through the standard authorization prompt.</li></ul><h2 id="search-indexing" tabindex="-1">Search &amp; Indexing <a class="header-anchor" href="#search-indexing" aria-label="Permalink to &quot;Search &amp; Indexing&quot;">​</a></h2><ul><li><strong>Searches cover everything they should</strong> — Properties arriving through webhooks and inner actions are now included when the search index is built; they were previously skipped, so they could not be found or matched on.</li><li><strong>Backfills cover the whole entity</strong> — A publisher nested inside another publisher is now included, so a backfill no longer rebuilds only part of an entity type.</li></ul><h2 id="agents-on-premise" tabindex="-1">Agents &amp; On-Premise <a class="header-anchor" href="#agents-on-premise" aria-label="Permalink to &quot;Agents &amp; On-Premise&quot;">​</a></h2><ul><li><strong>Settings changes stick on self-update</strong> — Updating an agent can now change which API it talks to; that setting previously reverted.</li><li><strong>Update an agent from the command line</strong> — <code>central agent update</code> triggers a self-update without the manual steps.</li><li><strong>A smoother Windows install</strong> — The installer finds your existing agent service rather than asking you to name it, completes an upgrade instead of hanging, and tells you what&#39;s wrong when it can&#39;t proceed.</li></ul><h2 id="reliability-monitoring" tabindex="-1">Reliability &amp; Monitoring <a class="header-anchor" href="#reliability-monitoring" aria-label="Permalink to &quot;Reliability &amp; Monitoring&quot;">​</a></h2><ul><li><strong>See exactly what a publisher read</strong> — Publisher runs record each source file consumed and the date window applied, and that window is shown in the UI.</li><li><strong>No files missed or read twice at a window edge</strong> — A file landing exactly on the boundary of a read window is now picked up once.</li><li><strong>Line-item order is preserved</strong> — Line items come back in the order they arrived, through storage and reload.</li><li><strong>Fewer syncs lost without explanation</strong> — Simultaneous updates to the same record no longer conflict, a record with an empty child list no longer stops the sync, and a connector error that isn&#39;t JSON no longer destroys the record of what happened.</li><li><strong>Clearer sign-in failures</strong> — An ambiguous email address is refused with an explanation instead of a server error, sign-in no longer fails intermittently, and errors during sign-in are shown rather than swallowed.</li></ul><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><strong>Looping Lists &amp; Custom Lists</strong> — A new guide with worked examples from source data to model.</li><li><strong>Value Formatting appendix</strong> and a completed transforms reference table.</li><li><strong>Inner actions</strong> and their filtering are now documented.</li><li><strong>Central Support page</strong> added to the guide.</li></ul><h2 id="upgrade-notes" tabindex="-1">Upgrade Notes <a class="header-anchor" href="#upgrade-notes" aria-label="Permalink to &quot;Upgrade Notes&quot;">​</a></h2><p><strong>Warehouse task renames.</strong> If you configured mappings against the <code>Pick</code>, <code>Pack</code> or <code>Wave</code> task types introduced in v5.15, they are now sub-types of the <strong><code>WarehouseTask</code></strong> entity type, named <code>PickTask</code>, <code>PackTask</code> and <code>WaveTask</code>. Re-select the entity type as <code>WarehouseTask</code> and pick the matching sub-type. Separately, the <code>WaveItem</code> entity type is now <code>WarehouseTaskLine</code>.</p><p>The associated key names changed with them — <code>PickId</code> → <code>PickTaskId</code>, <code>WaveId</code> → <code>WaveTaskId</code> — and <code>PackTaskId</code>, <code>ReceivingTaskId</code>, <code>ReceivingTaskLineId</code> and <code>PutawayTaskId</code> are new. There is no automatic alias from the old names. Contact Central Support if you&#39;d like help confirming whether this applies to you.</p><p><strong>Search re-index recommended.</strong> Search indexes built before this release omitted properties arriving through webhooks and inner actions, and backfills for nested publishers covered only part of their entity type. If you search or match on those properties, run a backfill after upgrading.</p>',31)])])}const p=t(o,[["render",i]]);export{u as __pageData,p as default};
